use proc_macro2::TokenStream;
use quote::quote;
use syn::{DeriveInput, Ident, LitStr, Type};

use crate::util;

/// Emit the RTTI declaration and `unsafe impl Message` for `ident`.
///
/// Shared between `#[derive(Message)]` and the message types generated by the
/// `#[messages]` attribute. The impl is sound by construction: the RTTI and
/// the impl are emitted for the same type in one expansion.
pub fn implement_message(
    ident: &Ident,
    answer: &TokenStream,
    rtti_name: &TokenStream,
    krate: &TokenStream,
) -> TokenStream {
    quote! {
        const _: () = {
            #krate::declare_message_rtti!(
                __DERIVED_MESSAGE_RTTI,
                #ident,
                #rtti_name
            );

            unsafe impl #krate::message::Message for #ident {
                const RTTI: &'static #krate::message::rtti::MessageRtti =
                    __DERIVED_MESSAGE_RTTI;

                type Answer = #answer;
            }
        };
    }
}

/// Parsed `#[message(...)]` configuration. Multiple `#[message(...)]`
/// attributes merge, duplicate keys are rejected.
#[derive(Default)]
struct MessageConfig {
    answer: Option<Type>,
    name: Option<LitStr>,
    crate_path: Option<LitStr>,
}

pub fn derive_message(input: DeriveInput) -> TokenStream {
    util::reject_generics(&input, "Message");

    let mut config = MessageConfig::default();
    for attr in &input.attrs {
        if !attr.path().is_ident("message") {
            continue;
        }

        // An unrecoverable parse error ends this attribute, not the derive:
        // the remaining attributes are still checked so all diagnostics
        // surface in one compiler pass.
        let result = attr.parse_nested_meta(|meta| {
            if meta.path.is_ident("answer") {
                util::set_value(&mut config.answer, &meta)
            } else if meta.path.is_ident("name") {
                util::set_value(&mut config.name, &meta)
            } else if meta.path.is_ident("crate") {
                util::set_value(&mut config.crate_path, &meta)
            } else {
                Err(meta.error("unknown key, expected one of `answer`, `name`, `crate`"))
            }
        });

        if let Err(error) = result {
            util::emit_syn_error(error);
        }
    }

    let ident = &input.ident;
    let answer = util::value_or_default(config.answer, quote!(()));
    let rtti_name = util::rtti_name(config.name, ident);
    let krate = util::krate_path(config.crate_path.as_ref());

    // (If diagnostics were emitted above, proc_macro_error discards this
    // output.)
    implement_message(ident, &answer, &rtti_name, &krate)
}
